INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Huffman-Codierung immer verlustfrei?', 2, '[{"text": "Ja", "correct": true, "because": "Originaldaten bleiben erhalten"}, {"text": "Nein", "correct": false, "because": "Verlustfrei ist nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Huffman-Codierung?', 3, '[{"text": "Datenkompression", "correct": true, "because": "Reduziert Speicherbedarf"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Sicherheit nicht im Fokus"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Kompression steht im Vordergrund"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für die Huffman-Codierung entscheidend?', 5, '[{"text": "Häufigkeit der Zeichen", "correct": true, "because": "Bestimmt Code-Länge"}, {"text": "Binärbaum", "correct": true, "because": "Strukturiert die Codes"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Kompressionsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Huffman-Codierung nutzt variable Code-Längen. b) Sie ist immer schneller als ZIP.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit hängt vom Kontext ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Huffman-Codierung?', 4, '[{"text": "Zeichenhäufigkeit", "correct": false, "because": "Grundlage der Codierung"}, {"text": "Baumstruktur", "correct": false, "because": "Erzeugt die Codes"}, {"text": "Textformatierung", "correct": true, "because": "Kein Einfluss auf Kompression"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Huffman-Codierung auch für Bilder geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Mit Vorverarbeitung möglich"}, {"text": "Nein", "correct": false, "because": "Nicht auf Text beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur nutze ich für die Huffman-Codierung?', 3, '[{"text": "Binärbaum", "correct": true, "because": "Effiziente Codezuweisung"}, {"text": "Array", "correct": false, "because": "Keine Hierarchie"}, {"text": "Liste", "correct": false, "because": "Keine Baumstruktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Effizienz der Huffman-Codierung?', 5, '[{"text": "Zeichenverteilung", "correct": true, "because": "Ungleichmäßigkeit steigert Kompression"}, {"text": "Datengröße", "correct": true, "because": "Größere Daten profitieren mehr"}, {"text": "Prozessorleistung", "correct": false, "because": "Sekundär"}, {"text": "Speicherlayout", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Huffman-Codierung ist optimal für ungleiche Häufigkeiten. b) Sie verdoppelt immer die Datengröße. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) widerspricht Kompression"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Huffman-Codierung?', 4, '[{"text": "Häufigkeitstabelle", "correct": false, "because": "Grundlage der Codierung"}, {"text": "Binärcodes", "correct": false, "because": "Ergebnis des Prozesses"}, {"text": "Grafische Darstellung", "correct": true, "because": "Nur für Visualisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Huffman-Codierung immer die beste Kompressionsmethode?', 2, '[{"text": "Nein", "correct": true, "because": "Kontextabhängig"}, {"text": "Ja", "correct": false, "because": "Andere Methoden können besser sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten eignen sich für Huffman-Codierung?', 4, '[{"text": "Text mit ungleicher Häufigkeit", "correct": true, "because": "Optimal für Varianz"}, {"text": "Binärdaten", "correct": true, "because": "Mit Anpassung komprimierbar"}, {"text": "Zufällige Daten", "correct": false, "because": "Wenig komprimierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Huffman-Codierung Daten verliert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Verlustfrei durch Dekodierung"}, {"text": "Ja", "correct": false, "because": "Verwechslung mit verlustbehafteten Methoden"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Huffman-Codierung?', 3, '[{"text": "Häufigkeitsanalyse", "correct": true, "because": "Bestimmt Effizienz"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Sekundär"}, {"text": "Speicherplatz", "correct": false, "because": "Ergebnis, kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Huffman-Codierung nutzt Präfixcodes. b) Sie ist für gleichverteilte Daten optimal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist bei Gleichverteilung ineffizient"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Huffman-Codierung essenziell?', 5, '[{"text": "Häufigkeitszählung", "correct": true, "because": "Basis der Codierung"}, {"text": "Baumerstellung", "correct": true, "because": "Erzeugt Codes"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}, {"text": "Datenverschiebung", "correct": false, "because": "Nicht Teil des Prozesses"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Huffman-Codierung unwichtig?', 3, '[{"text": "Code-Länge", "correct": false, "because": "Bestimmt Kompression"}, {"text": "Baumtiefe", "correct": false, "because": "Beeinflusst Effizienz"}, {"text": "Dateiformat", "correct": true, "because": "Nur Dateninhalt zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Huffman-Codierung für Audio geeignet?', 3, '[{"text": "Ja", "correct": true, "because": "Mit Vorverarbeitung möglich"}, {"text": "Nein", "correct": false, "because": "Nicht auf Text beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Huffman-Codierung adaptiv sein kann?', 2, '[{"text": "Ja", "correct": true, "because": "Dynamische Anpassung möglich"}, {"text": "Nein", "correct": false, "because": "Adaptives Huffman existiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für die Huffman-Codierung?', 4, '[{"text": "Häufigkeitstabelle", "correct": true, "because": "Grundlage der Codierung"}, {"text": "Zufällige Reihenfolge", "correct": false, "because": "Irrelevant"}, {"text": "Grafische Schnittstelle", "correct": false, "because": "Kein Fokus"}]');
